(window.__qhadithX=window.__qhadithX||{})[62]={"1":[{"c":"Sahih Muslim","r":"Hadith 863c","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-863c","x":"Jabir b. Abdullah reported:\n\nI was along with the Messenger of Allah (ﷺ) on Friday when a caravan arrived. The people went to it, and none but twelve persons were left behind and I was one of them; and it was on this occasion that this verse was revealed:\" And when they see merchandise or sport away to it, and leave thee standing\" (lxii. 1 1). they break","ar":"وَحَدَّثَنَا رِفَاعَةُ بْنُ الْهَيْثَمِ الْوَاسِطِيُّ، حَدَّثَنَا خَالِدٌ، - يَعْنِي الطَّحَّانَ - عَنْ حُصَيْنٍ، عَنْ سَالِمٍ، وَأَبِي، سُفْيَانَ عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ كُنَّا مَعَ النَّبِيِّ صلى الله عليه وسلم يَوْمَ الْجُمُعَةِ فَقَدِمَتْ سُوَيْقَةٌ قَالَ فَخَرَجَ النَّاسُ إِلَيْهَا فَلَمْ يَبْقَ إِلاَّ اثْنَا عَشَرَ رَجُلاً أَنَا فِيهِمْ - قَالَ - فَأَنْزَلَ اللَّهُ ‏{‏ وَإِذَا رَأَوْا تِجَارَةً أَوْ لَهْوًا انْفَضُّوا إِلَيْهَا وَتَرَكُوكَ قَائِمًا‏}‏ إِلَى آخِرِ الآيَةِ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 6, Book 44, Hadith 3310","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-6/Book-44/Hadith-3310","x":"Abu Hurairah said:\n\n\"We were with the Messenger of Allah when Surat Al-Jumuah was revealed, so he recited it until he reached: And other among them who have not yet joined them, A man said to him: ‘O Messenger of Allah! Who are these people who have not yet joined us?’ But he did not say anything to him.\" He said: \"Salman [Al-Farsi] was among us.\" He said: \"So the Messenger of Allah placed his hand upon Salman and said: ‘By the One in whose Hand is my soul! If faith were on Pleiades then men among these people would reach it.\"’","ar":"حَدَّثَنَا عَلِيُّ بْنِ حُجْرٍ، أَخْبَرَنَا عَبْدُ اللَّهِ بْنُ جَعْفَرٍ، حَدَّثَنِي ثَوْرُ بْنُ زَيْدٍ الدِّيلِيُّ، عَنْ أَبِي الْغَيْثِ، عَنْ أَبِي هُرَيْرَةَ، قَالَ كُنَّا عِنْدَ رَسُولِ اللَّهِ صلى الله عليه وسلم حِينَ أُنْزِلَتْ سُورَةُ الْجُمُعَةِ فَتَلاَهَا فَلَمَّا بَلَغَ ‏:‏ ‏(‏ وآخَرِينَ مِنْهُمْ لَمَّا يَلْحَقُوا بِهِمْ ‏)‏ قَالَ لَهُ رَجُلٌ يَا رَسُولَ اللَّهِ مَنْ هَؤُلاَءِ الَّذِينَ لَمْ يَلْحَقُوا بِنَا فَلَمْ يُكَلِّمْهُ قَالَ وَسَلْمَانُ الْفَارِسِيُّ فِينَا قَالَ فَوَضَعَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَدَهُ عَلَى سَلْمَانَ فَقَالَ ‏\"‏ وَالَّذِي نَفْسِي بِيَدِهِ لَوْ كَانَ الإِيمَانُ بِالثُّرَيَّا لَتَنَاوَلَهُ رِجَالٌ مِنْ هَؤُلاَءِ ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ غَرِيبٌ وَقَدْ رُوِيَ هَذَا الْحَدِيثُ عَنْ أَبِي هُرَيْرَةَ عَنِ النَّبِيِّ صلى الله عليه وسلم مِنْ غَيْرِ وَجْهٍ ‏.‏ وَعَبْدُ اللَّهِ بْنُ جَعْفَرٍ هُوَ وَالِدُ عَلِيِّ بْنِ الْمَدِينِيِّ ضَعَّفَهُ يَحْيَى بْنُ مَعِينٍ ‏.‏ ثَوْرُ بْنُ زَيْدٍ مَدَنِيٌّ وَثَوْرُ بْنُ يَزِيدَ شَامِيٌّ وَأَبُو الْغَيْثِ اسْمُهُ سَالِمٌ مَوْلَى عَبْدِ اللَّهِ بْنِ مُطِيعٍ مَدَنِيٌّ ثِقَةٌ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 6, Book 46, Hadith 3933","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-6/Book-46/Hadith-3933","x":"Narrated Abu Hurairah:\n\n\"We were with the Messenger of Allah (ﷺ) when Surat Al-Jumu'ah was revealed, so he recited it until he reached: 'And others among them who have not yet joined them (62:3).' A man said to him: 'O Messenger of Allah! Who are these people who have not yet joined us?' But he did not say anything to him.\" He said: \"Salman Al-Farisi was among us.\" He said: \"So the Messenger of Allah (ﷺ) placed his hand upon Salman and said: 'By the One Whose Hand is my soul! If faith were on Pleiades then men among these people would reach it.'\"","ar":"حَدَّثَنَا عَلِيُّ بْنُ حُجْرٍ، قَالَ حَدَّثَنَا عَبْدُ اللَّهِ بْنُ جَعْفَرٍ، قَالَ حَدَّثَنِي ثَوْرُ بْنُ زَيْدٍ الدِّيلِيُّ، عَنْ أَبِي الْغَيْثِ، عَنْ أَبِي هُرَيْرَةَ، قَالَ كُنَّا عِنْدَ رَسُولِ اللَّهِ صلى الله عليه وسلم حِينَ أُنْزِلَتْ سُورَةُ الْجُمُعَةِ فَتَلاَهَا فَلَمَّا بَلَغَ ‏:‏ ‏(‏ وآخَرِينَ مِنْهُمْ لَمَّا يَلْحَقُوا بِهِمْ ‏)‏ قَالَ لَهُ رَجُلٌ يَا رَسُولَ اللَّهِ مَنْ هَؤُلاَءِ الَّذِينَ لَمْ يَلْحَقُوا بِنَا فَلَمْ يُكَلِّمْهُ ‏.‏ قَالَ وَسَلْمَانُ الْفَارِسِيُّ فِينَا ‏.‏ قَالَ فَوَضَعَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَدَهُ عَلَى سَلْمَانَ فَقَالَ ‏\"‏ وَالَّذِي نَفْسِي بِيَدِهِ لَوْ كَانَ الإِيمَانُ بِالثُّرَيَّا لَتَنَاوَلَهُ رِجَالٌ مِنْ هَؤُلاَءِ ‏\"‏ ‏.‏ هَذَا حَدِيثٌ حَسَنٌ وَقَدْ رُوِيَ مِنْ غَيْرِ وَجْهٍ عَنْ أَبِي هُرَيْرَةَ عَنِ النَّبِيِّ صلى الله عليه وسلم ‏.‏ وَأَبُو الْغَيْثِ اسْمُهُ سَالِمٌ مَوْلَى عَبْدِ اللَّهِ بْنِ مُطِيعٍ مَدَنِيٌّ ‏.‏","v":[]}],"2":[{"c":"Jami` at-Tirmidhi","r":"Volume 6, Book 46, Hadith 3933","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-6/Book-46/Hadith-3933","x":"Narrated Abu Hurairah:\n\n\"We were with the Messenger of Allah (ﷺ) when Surat Al-Jumu'ah was revealed, so he recited it until he reached: 'And others among them who have not yet joined them (62:3).' A man said to him: 'O Messenger of Allah! Who are these people who have not yet joined us?' But he did not say anything to him.\" He said: \"Salman Al-Farisi was among us.\" He said: \"So the Messenger of Allah (ﷺ) placed his hand upon Salman and said: 'By the One Whose Hand is my soul! If faith were on Pleiades then men among these people would reach it.'\"","ar":"حَدَّثَنَا عَلِيُّ بْنُ حُجْرٍ، قَالَ حَدَّثَنَا عَبْدُ اللَّهِ بْنُ جَعْفَرٍ، قَالَ حَدَّثَنِي ثَوْرُ بْنُ زَيْدٍ الدِّيلِيُّ، عَنْ أَبِي الْغَيْثِ، عَنْ أَبِي هُرَيْرَةَ، قَالَ كُنَّا عِنْدَ رَسُولِ اللَّهِ صلى الله عليه وسلم حِينَ أُنْزِلَتْ سُورَةُ الْجُمُعَةِ فَتَلاَهَا فَلَمَّا بَلَغَ ‏:‏ ‏(‏ وآخَرِينَ مِنْهُمْ لَمَّا يَلْحَقُوا بِهِمْ ‏)‏ قَالَ لَهُ رَجُلٌ يَا رَسُولَ اللَّهِ مَنْ هَؤُلاَءِ الَّذِينَ لَمْ يَلْحَقُوا بِنَا فَلَمْ يُكَلِّمْهُ ‏.‏ قَالَ وَسَلْمَانُ الْفَارِسِيُّ فِينَا ‏.‏ قَالَ فَوَضَعَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَدَهُ عَلَى سَلْمَانَ فَقَالَ ‏\"‏ وَالَّذِي نَفْسِي بِيَدِهِ لَوْ كَانَ الإِيمَانُ بِالثُّرَيَّا لَتَنَاوَلَهُ رِجَالٌ مِنْ هَؤُلاَءِ ‏\"‏ ‏.‏ هَذَا حَدِيثٌ حَسَنٌ وَقَدْ رُوِيَ مِنْ غَيْرِ وَجْهٍ عَنْ أَبِي هُرَيْرَةَ عَنِ النَّبِيِّ صلى الله عليه وسلم ‏.‏ وَأَبُو الْغَيْثِ اسْمُهُ سَالِمٌ مَوْلَى عَبْدِ اللَّهِ بْنِ مُطِيعٍ مَدَنِيٌّ ‏.‏","v":[]}],"3":[{"c":"Sahih Bukhari","r":"Hadith 4897","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4897","x":"Narrated Abu Huraira:\n\nWhile we were sitting with the Prophet (ﷺ) Surat Al-Jumu'a was revealed to him, and when the Verse, \"And He (Allah) has sent him (Muhammad) also to other (Muslims).....' (62.3) was recited by the Prophet, I said, \"Who are they, O Allah's Messenger (ﷺ)?\" The Prophet (ﷺ) did not reply till I repeated my question thrice. At that time, Salman Al-Farisi was with us. So Allah's Messenger (ﷺ) put his hand on Salman, saying, \"If Faith were at (the place of) Ath-Thuraiya (pleiades, the highest star), even then (some men or man from these people (i.e. Salman's folk) would attain it.\"","ar":"حَدَّثَنِي عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ، قَالَ حَدَّثَنِي سُلَيْمَانُ بْنُ بِلاَلٍ، عَنْ ثَوْرٍ، عَنْ أَبِي الْغَيْثِ، عَنْ أَبِي هُرَيْرَةَ، رضى الله عنه قَالَ كُنَّا جُلُوسًا عِنْدَ النَّبِيِّ صلى الله عليه وسلم فَأُنْزِلَتْ عَلَيْهِ سُورَةُ الْجُمُعَةِ ‏{‏وَآخَرِينَ مِنْهُمْ لَمَّا يَلْحَقُوا بِهِمْ‏}‏ قَالَ قُلْتُ مَنْ هُمْ يَا رَسُولَ اللَّهِ فَلَمْ يُرَاجِعْهُ حَتَّى سَأَلَ ثَلاَثًا، وَفِينَا سَلْمَانُ الْفَارِسِيُّ، وَضَعَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَدَهُ عَلَى سَلْمَانَ ثُمَّ قَالَ ‏\"‏ لَوْ كَانَ الإِيمَانُ عِنْدَ الثُّرَيَّا لَنَالَهُ رِجَالٌ ـ أَوْ رَجُلٌ ـ مِنْ هَؤُلاَءِ ‏\"‏‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 6, Book 46, Hadith 3933","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-6/Book-46/Hadith-3933","x":"Narrated Abu Hurairah:\n\n\"We were with the Messenger of Allah (ﷺ) when Surat Al-Jumu'ah was revealed, so he recited it until he reached: 'And others among them who have not yet joined them (62:3).' A man said to him: 'O Messenger of Allah! Who are these people who have not yet joined us?' But he did not say anything to him.\" He said: \"Salman Al-Farisi was among us.\" He said: \"So the Messenger of Allah (ﷺ) placed his hand upon Salman and said: 'By the One Whose Hand is my soul! If faith were on Pleiades then men among these people would reach it.'\"","ar":"حَدَّثَنَا عَلِيُّ بْنُ حُجْرٍ، قَالَ حَدَّثَنَا عَبْدُ اللَّهِ بْنُ جَعْفَرٍ، قَالَ حَدَّثَنِي ثَوْرُ بْنُ زَيْدٍ الدِّيلِيُّ، عَنْ أَبِي الْغَيْثِ، عَنْ أَبِي هُرَيْرَةَ، قَالَ كُنَّا عِنْدَ رَسُولِ اللَّهِ صلى الله عليه وسلم حِينَ أُنْزِلَتْ سُورَةُ الْجُمُعَةِ فَتَلاَهَا فَلَمَّا بَلَغَ ‏:‏ ‏(‏ وآخَرِينَ مِنْهُمْ لَمَّا يَلْحَقُوا بِهِمْ ‏)‏ قَالَ لَهُ رَجُلٌ يَا رَسُولَ اللَّهِ مَنْ هَؤُلاَءِ الَّذِينَ لَمْ يَلْحَقُوا بِنَا فَلَمْ يُكَلِّمْهُ ‏.‏ قَالَ وَسَلْمَانُ الْفَارِسِيُّ فِينَا ‏.‏ قَالَ فَوَضَعَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَدَهُ عَلَى سَلْمَانَ فَقَالَ ‏\"‏ وَالَّذِي نَفْسِي بِيَدِهِ لَوْ كَانَ الإِيمَانُ بِالثُّرَيَّا لَتَنَاوَلَهُ رِجَالٌ مِنْ هَؤُلاَءِ ‏\"‏ ‏.‏ هَذَا حَدِيثٌ حَسَنٌ وَقَدْ رُوِيَ مِنْ غَيْرِ وَجْهٍ عَنْ أَبِي هُرَيْرَةَ عَنِ النَّبِيِّ صلى الله عليه وسلم ‏.‏ وَأَبُو الْغَيْثِ اسْمُهُ سَالِمٌ مَوْلَى عَبْدِ اللَّهِ بْنِ مُطِيعٍ مَدَنِيٌّ ‏.‏","v":[]}],"10":[{"c":"Muwatta Malik","r":"Book 39, Hadith 1494","u":"https://quranx.com/Hadith/Malik/In-Book/Book-39/Hadith-1494","x":"Malik related to me from Humayd ibn Qays al-Makki that a son of al-Mutawakkil had a mukatab who died at Makka and left (enough to pay) the rest of his kitaba and he owed some debts to people. He also left a daughter. The governor of Makka was not certain about how to judge in the case, so he wrote to Abd al-Malik ibn Marwan to ask him about it. Abd al-Malik wrote to him, \"Begin with the debts owed to people, and then pay what remains of his kitaba. Then divide what remains of the property between the daughter and the master.\" Malik said, \"What is done among us is that the master of a slave does not have to give his slave a kitaba if he asks for it. I have not heard of any of the Imams forcing a man to give a kitaba to his slave. I heard that one of the people of knowledge, when someone asked about that and mentioned that Allah the Blessed, the Exalted, said, 'Give them their kitaba, if you know some good in them' (Sura 24 ayat 33) recited these two ayats, 'When you are free of the state of ihram, then hunt for game.' (Sura 5 ayat 3) 'When the prayer is finished, scatter in the land and seek Allah's favour.' \" (Sura 62 ayat 10) Malik commented, \"It is a way of doing things for which Allah, the Mighty, the Majestic, has given permission to people, and it is not obligatory for them.\" Malik said, \"I heard one of the people of knowledge say about the word of Allah, the Blessed, the Exalted, 'Give them of the wealth which Allah has given you,' that it meant that a man give his slave a kitaba and then reduce the end of his kitaba for him by some specific amount.\" Malik said, \"This is what I have heard from the people of knowledge and what I see people doing here.\" Malik said, \"I have heard that Abdullah ibn Umar gave one of his slaves his kitaba for 35,000 dirhams, and then reduced the end of his kitaba by 5,000 dirhams.\" Malik said, \"What is done among us is that when a master gives a mukatab his kitaba, the mukatab's property goes with him but his children do not go with him unless he stipulates that in his kitaba.\" Yahya said, \"I heard Malik say that if a mukatab whose master had given him a kitaba had a slave- girl who was pregnant by him, and neither he nor his master knew that on the day he was given his kitaba, the child did not follow him because he was not included in the kitaba. He belonged to the master. As for the slave-girl, she belonged to the mukatab because she was his property.\" Malik said that if a man and his wife's son (by another husband) inherited a mukatab from the wife and the mukatab died before he had completed his kitaba, they divided his inheritance between them according to the Book of Allah. If the slave paid his kitaba and then died, his inheritance went to the son of the woman, and the husband had nothing of his inheritance. Malik said that if a mukatab gave his own slave a kitaba, the situation was looked at. If he wanted to do his slave a favour and it was obvious by his making it easy for him, that was not permitted. If he was giving him a kitaba from desire to find money to pay off his own kitaba, that was permitted for him. Malik said that if a man had intercourse with a mukataba of his and she became pregnant by him, she had an option. If she liked she could be an umm walad. If she wished, she could confirm her kitaba. If she did not conceive, she still had her kitaba. Malik said, \"The generally agreed on way of doing things among us about a slave who is owned by two men is that one of them does not give a kitaba for his share, whether or not his companion gives him permission to do so, unless they both write the kitaba together, because that alone would effect setting him free. If the slave were to fulfil what he had agreed on to free half of himself, and then the one who had given a kitaba for half of him was not obliged to complete his setting free, that would be in opposition to the words of the Messenger of Allah, may Allah bless him and grant him peace. 'If someone frees his share in a slave and has enough money to cover the full price of the slave, justly evaluated for him, he must give his partners their shares, so the slave is completely free. ' \" Malik said, \"If he is not aware of that until the mukatab has met the terms or before he has met them the owner who has written him the kitaba returns what he has taken from the mukatab to him, and then he and his partner divide him according to their original shares and the kitaba is invalid. He is the slave of both of them in his original state.\" Malik spoke about a mukatab who was owned by two men and one of them granted him a delay in the payment of the right which he was owed, and the other refused to defer it, and so the one who refused to defer the payment exacted his part of the due. Malik said that if the mukatab then died and left property which did not complete his kitaba, \"They divide it according to what they are still owed by him. Each of them takes according to his share. If the mukatab leaves more than his kitaba, each of them takes what remains to them of the kitaba, and what remains after that is divided equally between them. If the mukatab is unable to pay his kitaba fully and the one who did not allow him to defer his payment has exacted more than his associate did, the slave is still divided equally between them, and he does not return to his associates the excess of what he has exacted, because he only exacted his right with the permission of his associate. If one of them remits what is owed to him and then his associate exacts part of what he is owed by him and then the mukatab is unable to pay, he belongs to both of them. And the one who has exacted something does not return anything because he only demanded what he was owed. That is like the debt of two men in one writing against one man. One of them grants him time to pay and the other is greedy and exacts his due. Then the debtor goes bankrupt. The one who exacted his due does not have to return any of what he took.\"","ar":"وَحَدَّثَنِي مَالِكٌ، عَنْ حُمَيْدِ بْنِ قَيْسٍ الْمَكِّيِّ، أَنَّ مُكَاتَبًا، كَانَ لاِبْنِ الْمُتَوَكِّلِ هَلَكَ بِمَكَّةَ وَتَرَكَ عَلَيْهِ بَقِيَّةً مِنْ كِتَابَتِهِ وَدُيُونًا لِلنَّاسِ وَتَرَكَ ابْنَتَهُ فَأَشْكَلَ عَلَى عَامِلِ مَكَّةَ الْقَضَاءُ فِيهِ فَكَتَبَ إِلَى عَبْدِ الْمَلِكِ بْنِ مَرْوَانَ يَسْأَلُهُ عَنْ ذَلِكَ فَكَتَبَ إِلَيْهِ عَبْدُ الْمَلِكِ أَنِ ابْدَأْ بِدُيُونِ النَّاسِ ثُمَّ اقْضِ مَا بَقِيَ مِنْ كِتَابَتِهِ ثُمَّ اقْسِمْ مَا بَقِيَ مِنْ مَالِهِ بَيْنَ ابْنَتِهِ وَمَوْلاَهُ ‏.‏ قَالَ مَالِكٌ الأَمْرُ عِنْدَنَا أَنَّهُ لَيْسَ عَلَى سَيِّدِ الْعَبْدِ أَنْ يُكَاتِبَهُ إِذَا سَأَلَهُ ذَلِكَ وَلَمْ أَسْمَعْ أَنَّ أَحَدًا مِنَ الأَئِمَّةِ أَكْرَهَ رَجُلاً عَلَى أَنْ يُكَاتِبَ عَبْدَهُ وَقَدْ سَمِعْتُ بَعْضَ أَهْلِ الْعِلْمِ إِذَا سُئِلَ عَنْ ذَلِكَ فَقِيلَ لَهُ إِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى يَقُولُ ‏{‏فَكَاتِبُوهُمْ إِنْ عَلِمْتُمْ فِيهِمْ خَيْرًا‏}‏ ‏.‏ يَتْلُو هَاتَيْنِ الآيَتَيْنِ ‏{‏وَإِذَا حَلَلْتُمْ فَاصْطَادُوا‏}‏ ‏.‏ ‏{‏فَإِذَا قُضِيَتِ الصَّلاَةُ فَانْتَشِرُوا فِي الأَرْضِ وَابْتَغُوا مِنْ فَضْلِ اللَّهِ‏}‏ ‏.‏ قَالَ مَالِكٌ وَإِنَّمَا ذَلِكَ أَمْرٌ أَذِنَ اللَّهُ عَزَّ وَجَلَّ فِيهِ لِلنَّاسِ وَلَيْسَ بِوَاجِبٍ عَلَيْهِمْ ‏.‏ قَالَ مَالِكٌ وَسَمِعْتُ بَعْضَ أَهْلِ الْعِلْمِ يَقُولُ فِي قَوْلِ اللَّهِ تَبَارَكَ وَتَعَالَى ‏{‏وَآتُوهُمْ مِنْ مَالِ اللَّهِ الَّذِي آتَاكُمْ‏}‏ ‏.‏ إِنَّ ذَلِكَ أَنْ يُكَاتِبَ الرَّجُلُ غُلاَمَهُ ثُمَّ يَضَعُ عَنْهُ مِنْ آخِرِ كِتَابَتِهِ شَيْئًا مُسَمًّى ‏.‏ قَالَ مَالِكٌ فَهَذَا الَّذِي سَمِعْتُ مِنْ أَهْلِ الْعِلْمِ وَأَدْرَكْتُ عَمَلَ النَّاسِ عَلَى ذَلِكَ عِنْدَنَا ‏.‏ قَالَ مَالِكٌ وَقَدْ بَلَغَنِي أَنَّ عَبْدَ اللَّهِ بْنَ عُمَرَ كَاتَبَ غُلاَمًا لَهُ عَلَى خَمْسَةٍ وَثَلاَثِينَ أَلْفَ دِرْهَمٍ ثُمَّ وَضَعَ عَنْهُ مِنْ آخِرِ كِتَابَتِهِ خَمْسَةَ آلاَفِ دِرْهَمٍ ‏.‏ قَالَ مَالِكٌ الأَمْرُ عِنْدَنَا أَنَّ الْمُكَاتَبَ إِذَا كَاتَبَهُ سَيِّدُهُ تَبِعَهُ مَالُهُ وَلَمْ يَتْبَعْهُ وَلَدُهُ إِلاَّ أَنْ يَشْتَرِطَهُمْ فِي كِتَابَتِهِ ‏.‏ قَالَ يَحْيَى سَمِعْتُ مَالِكًا يَقُولُ فِي الْمُكَاتَبِ يُكَاتِبُهُ سَيِّدُهُ وَلَهُ جَارِيَةٌ بِهَا حَبَلٌ مِنْهُ لَمْ يَعْلَمْ بِهِ هُوَ وَلاَ سَيِّدُهُ يَوْمَ كِتَابَتِهِ فَإِنَّهُ لاَ يَتْبَعُهُ ذَلِكَ الْوَلَدُ لأَنَّهُ لَمْ يَكُنْ دَخَلَ فِي كِتَابَتِهِ وَهُوَ لِسَيِّدِهِ فَأَمَّا الْجَارِيَةُ فَإِنَّهَا لِلْمُكَاتَبِ لأَنَّهَا مِنْ مَالِهِ ‏.‏ قَالَ مَالِكٌ فِي رَجُلٍ وَرِثَ مُكَاتَبًا مِنِ امْرَأَتِهِ هُوَ وَابْنُهَا إِنَّ الْمُكَاتَبَ إِنْ مَاتَ قَبْلَ أَنْ يَقْضِيَ كِتَابَتَهُ اقْتَسَمَا مِيرَاثَهُ عَلَى كِتَابِ اللَّهِ وَإِنْ أَدَّى كِتَابَتَهُ ثُمَّ مَاتَ فَمِيرَاثُهُ لاِبْنِ الْمَرْأَةِ وَلَيْسَ لِلزَّوْجِ مِنْ مِيرَاثِهِ شَىْءٌ ‏.‏ قَالَ مَالِكٌ فِي الْمُكَاتَبِ يُكَاتِبُ عَبْدَهُ قَالَ يُنْظَرُ فِي ذَلِكَ فَإِنْ كَانَ إِنَّمَا أَرَادَ الْمُحَابَاةَ لِعَبْدِهِ وَعُرِفَ ذَلِكَ مِنْهُ بِالتَّخْفِيفِ عَنْهُ فَلاَ يَجُوزُ ذَلِكَ وَإِنْ كَانَ إِنَّمَا كَاتَبَهُ عَلَى وَجْهِ الرَّغْبَةِ وَطَلَبِ الْمَالِ وَابْتِغَاءِ الْفَضْلِ وَالْعَوْنِ عَلَى كِتَابَتِهِ فَذَلِكَ جَائِزٌ لَهُ ‏.‏ قَالَ مَالِكٌ فِي رَجُلٍ وَطِئَ مُكَاتَبَةً لَهُ إِنَّهَا إِنْ حَمَلَتْ فَهِيَ بِالْخِيَارِ إِنْ شَاءَتْ كَانَتْ أُمَّ وَلَدٍ وَإِنْ شَاءَتْ قَرَّتْ عَلَى كِتَابَتِهَا فَإِنْ لَمْ تَحْمِلْ فَهِيَ عَلَى كِتَابَتِهَا ‏.‏ قَالَ مَالِكٌ الأَمْرُ الْمُجْتَمَعُ عَلَيْهِ عِنْدَنَا فِي الَعَبْدِ يَكُونُ بَيْنَ الرَّجُلَيْنِ إِنَّ أَحَدَهُمَا لاَ يُكَاتِبُ نَصِيبَهُ مِنْهُ أَذِنَ لَهُ بِذَلِكَ صَاحِبُهُ أَوْ لَمْ يَأْذَنْ إِلاَّ أَنْ يُكَاتِبَاهُ جَمِيعًا لأَنَّ ذَلِكَ يَعْقِدُ لَهُ عِتْقًا وَيَصِيرُ إِذَا أَدَّى الْعَبْدُ مَا كُوتِبَ عَلَيْهِ إِلَى أَنْ يَعْتِقَ نِصْفُهُ وَلاَ يَكُونُ عَلَى الَّذِي كَاتَبَ بَعْضَهُ أَنْ يَسْتَتِمَّ عِتْقَهُ فَذَلِكَ خِلاَفُ مَا قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ مَنْ أَعْتَقَ شِرْكًا لَهُ فِي عَبْدٍ قُوِّمَ عَلَيْهِ قِيمَةَ الْعَدْلِ ‏\"‏ ‏.‏ قَالَ مَالِكٌ فَإِنْ جَهِلَ ذَلِكَ حَتَّى يُؤَدِّيَ الْمُكَاتَبُ أَوْ قَبْلَ أَنْ يُؤَدِّيَ رَدَّ إِلَيْهِ الَّذِي كَاتَبَهُ مَا قَبَضَ مِنَ الْمُكَاتَبِ فَاقْتَسَمَهُ هُوَ وَشَرِيكُهُ عَلَى قَدْرِ حِصَصِهِمَا وَبَطَلَتْ كِتَابَتُهُ وَكَانَ عَبْدًا لَهُمَا عَلَى حَالِهِ الأُولَى ‏.‏ قَالَ مَالِكٌ فِي مُكَاتَبٍ بَيْنَ رَجُلَيْنِ فَأَنْظَرَهُ أَحَدُهُمَا بِحَقِّهِ الَّذِي عَلَيْهِ وَأَبَى الآخَرُ أَنْ يُنْظِرَهُ فَاقْتَضَى الَّذِي أَبَى أَنْ يُنْظِرَهُ بَعْضَ حَقِّهِ ثُمَّ مَاتَ الْمُكَاتَبُ وَتَرَكَ مَالاً لَيْسَ فِيهِ وَفَاءٌ مِنْ كِتَابَتِهِ قَالَ مَالِكٌ يَتَحَاصَّانِ بِقَدْرِ مَا بَقِيَ لَهُمَا عَلَيْهِ يَأْخُذُ كُلُّ وَاحِدٍ مِنْهُمَا بِقَدْرِ حِصَّتِهِ فَإِنْ تَرَكَ الْمُكَاتَبُ فَضْلاً عَنْ كِتَابَتِهِ أَخَذَ كُلُّ وَاحِدٍ مِنْهُمَا مَا بَقِيَ مِنَ الْكِتَابَةِ وَكَانَ مَا بَقِيَ بَيْنَهُمَا بِالسَّوَاءِ فَإِنْ عَجَزَ الْمُكَاتَبُ وَقَدِ اقْتَضَى الَّذِي لَمْ يُنْظِرْهُ أَكْثَرَ مِمَّا اقْتَضَى صَاحِبُهُ كَانَ الْعَبْدُ بَيْنَهُمَا نِصْفَيْنِ وَلاَ يَرُدُّ عَلَى صَاحِبِهِ فَضْلَ مَا اقْتَضَى لأَنَّهُ إِنَّمَا اقْتَضَى الَّذِي لَهُ بِإِذْنِ صَاحِبِهِ وَإِنْ وَضَعَ عَنْهُ أَحَدُهُمَا الَّذِي لَهُ ثُمَّ اقْتَضَى صَاحِبُهُ بَعْضَ الَّذِي لَهُ عَلَيْهِ ثُمَّ عَجَزَ فَهُوَ بَيْنَهُمَا وَلاَ يَرُدُّ الَّذِي اقْتَضَى عَلَى صَاحِبِهِ شَيْئًا لأَنَّهُ إِنَّمَا اقْتَضَى الَّذِي لَهُ عَلَيْهِ وَذَلِكَ بِمَنْزِلَةِ الدَّيْنِ لِلرَّجُلَيْنِ بِكِتَابٍ وَاحِدٍ عَلَى رَجُلٍ وَاحِدٍ فَيُنْظِرُهُ أَحَدُهُمَا وَيَشِحُّ الآخَرُ فَيَقْتَضِي بَعْضَ حَقِّهِ ثُمَّ يُفْلِسُ الْغَرِيمُ فَلَيْسَ عَلَى الَّذِي اقْتَضَى أَنْ يَرُدَّ شَيْئًا مِمَّا أَخَذَ ‏.","v":[]}],"11":[{"c":"Sahih Bukhari","r":"Hadith 936","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-936","x":"Narrated Jabir bin `Abdullah:\n\nWhile we were praying (Jumua Khutba & prayer) with the Prophet (p.b.u.h), some camels loaded with food, arrived (from Sham). The people diverted their attention towards the camels (and left the mosque), and only twelve persons remained with the Prophet. So this verse was revealed: \"But when they see Some bargain or some amusement, They disperse headlong to it, And leave you standing.\" (62.11)","ar":"حَدَّثَنَا مُعَاوِيَةُ بْنُ عَمْرٍو، قَالَ حَدَّثَنَا زَائِدَةُ، عَنْ حُصَيْنٍ، عَنْ سَالِمِ بْنِ أَبِي الْجَعْدِ، قَالَ حَدَّثَنَا جَابِرُ بْنُ عَبْدِ اللَّهِ، قَالَ بَيْنَمَا نَحْنُ نُصَلِّي مَعَ النَّبِيِّ صلى الله عليه وسلم إِذْ أَقْبَلَتْ عِيرٌ تَحْمِلُ طَعَامًا، فَالْتَفَتُوا إِلَيْهَا حَتَّى مَا بَقِيَ مَعَ النَّبِيِّ صلى الله عليه وسلم إِلاَّ اثْنَا عَشَرَ رَجُلاً، فَنَزَلَتْ هَذِهِ الآيَةُ ‏{‏وَإِذَا رَأَوْا تِجَارَةً أَوْ لَهْوًا انْفَضُّوا إِلَيْهَا وَتَرَكُوكَ قَائِمًا‏}‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2058","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2058","x":"Narrated Jabir:\n\nWhile we were offering the prayer with the Prophet (ﷺ) a caravan carrying food came from Sham. The people looked towards the caravan (and went to it) and only twelve persons remained with the Prophet. So, the Divine Inspiration came; \"But when they see some bargain or some amusement, they disperse headlong to it.\" (62.11)","ar":"حَدَّثَنَا طَلْقُ بْنُ غَنَّامٍ، حَدَّثَنَا زَائِدَةُ، عَنْ حُصَيْنٍ، عَنْ سَالِمٍ، قَالَ حَدَّثَنِي جَابِرٌ ـ رضى الله عنه ـ قَالَ بَيْنَمَا نَحْنُ نُصَلِّي مَعَ النَّبِيِّ صلى الله عليه وسلم إِذْ أَقْبَلَتْ مِنَ الشَّأْمِ عِيرٌ، تَحْمِلُ طَعَامًا، فَالْتَفَتُوا إِلَيْهَا، حَتَّى مَا بَقِيَ مَعَ النَّبِيِّ صلى الله عليه وسلم إِلاَّ اثْنَا عَشَرَ رَجُلاً فَنَزَلَتْ ‏{‏وَإِذَا رَأَوْا تِجَارَةً أَوْ لَهْوًا انْفَضُّوا إِلَيْهَا‏}‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2064","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2064","x":"Narrated Jabir:\n\nA caravan arrived (at Medina) while we were offering the Jumua prayer with the Prophet. The people left out for the caravan, with the exception of twelve persons. Then this Verse was revealed: 'But when they see some bargain or some amusement, they disperse headlong to it and leave you standing.\" (62.11)","ar":"حَدَّثَنِي مُحَمَّدٌ، قَالَ حَدَّثَنِي مُحَمَّدُ بْنُ فُضَيْلٍ، عَنْ حُصَيْنٍ، عَنْ سَالِمِ بْنِ أَبِي الْجَعْدِ، عَنْ جَابِرٍ ـ رضى الله عنه ـ قَالَ أَقْبَلَتْ عِيرٌ، وَنَحْنُ نُصَلِّي مَعَ النَّبِيِّ صلى الله عليه وسلم الْجُمُعَةَ، فَانْفَضَّ النَّاسُ إِلاَّ اثْنَىْ عَشَرَ رَجُلاً، فَنَزَلَتْ هَذِهِ الآيَةُ ‏{‏وَإِذَا رَأَوْا تِجَارَةً أَوْ لَهْوًا انْفَضُّوا إِلَيْهَا وَتَرَكُوكَ قَائِمًا ‏}‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4899","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4899","x":"Narrated Jabir bin `Abdullah:\n\nA caravan of merchandise arrived at Medina on a Friday while we were with the Prophet (ﷺ) All the people left (the Prophet (ﷺ) and headed for the caravan) except twelve persons. Then Allah revealed:-- 'But when they see some bargain or some amusement they disperse headlong to it.'..(62.11)","ar":"حَدَّثَنِي حَفْصُ بْنُ عُمَرَ، حَدَّثَنَا خَالِدُ بْنُ عَبْدِ اللَّهِ، حَدَّثَنَا حُصَيْنٌ، عَنْ سَالِمِ بْنِ أَبِي الْجَعْدِ، وَعَنْ أَبِي سُفْيَانَ، عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ ـ رضى الله عنهما ـ قَالَ أَقْبَلَتْ عِيرٌ يَوْمَ الْجُمُعَةِ وَنَحْنُ مَعَ النَّبِيِّ صلى الله عليه وسلم فَثَارَ النَّاسُ إِلاَّ اثْنَا عَشَرَ رَجُلاً فَأَنْزَلَ اللَّهُ ‏{‏وَإِذَا رَأَوْا تِجَارَةً أَوْ لَهْوًا انْفَضُّوا إِلَيْهَا‏}‏","v":[]},{"c":"Sunan Ibn Majah","r":"Volume 2, Book 5, Hadith 1108","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-2/Book-5/Hadith-1108","x":"‘Alqamah narrated that ‘Abdullah was asked whether the Prophet (ﷺ) used to deliver the sermon standing or sitting. He said:\n\n\"Have you not read the Verse: ‘...and leave you (Muhammad) standing (while delivering the Friday sermon?\" [62:11]","ar":"حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا ابْنُ أَبِي غَنِيَّةَ، عَنِ الأَعْمَشِ، عَنْ إِبْرَاهِيمَ، عَنْ عَلْقَمَةَ، عَنْ عَبْدِ اللَّهِ، أَنَّهُ سُئِلَ أَكَانَ النَّبِيُّ ـ صلى الله عليه وسلم ـ يَخْطُبُ قَائِمًا أَوْ قَاعِدًا؟ قَالَ أَوَمَا تَقْرَأُ {وَتَرَكُوكَ قَائِمًا}‏ قَالَ أَبُو عَبْدِ اللَّهِ غَرِيبٌ لاَ يُحَدِّثُ بِهِ إِلاَّ ابْنُ أَبِي شَيْبَةَ وَحْدَهُ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 6, Book 44, Hadith 3311","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-6/Book-44/Hadith-3311","x":"Jabir said:\n\n\"The Prophet was standing and delivering a Khutbah for us on one Friday, when a caravan arrived in Al-Madinah. So the Companions of the Messenger of Allah rushed off until only twelve men remained. Among them were Abu Bakr and Umar. And This Ayah was revealed: And when they see some merchandise or some amusement, they disperse headlong to it.\"","ar":"حَدَّثَنَا أَحْمَدُ بْنُ مَنِيعٍ، حَدَّثَنَا هُشَيْمٌ، أَخْبَرَنَا حُصَيْنٌ، عَنْ أَبِي سُفْيَانَ، عَنْ جَابِرٍ، قَالَ بَيْنَمَا النَّبِيُّ صلى الله عليه وسلم يَخْطُبُ يَوْمَ الْجُمُعَةِ قَائِمًا إِذْ قَدِمَتْ عِيرٌ الْمَدِينَةَ فَابْتَدَرَهَا أَصْحَابُ رَسُولِ اللَّهِ صلى الله عليه وسلم حَتَّى لَمْ يَبْقَ مِنْهُمْ إِلاَّ اثْنَا عَشَرَ رَجُلاً فِيهِمْ أَبُو بَكْرٍ وَعُمَرُ وَنَزَلَتِ الآيَةُ ‏:‏ ‏(‏ وإِذَا رَأَوْا تِجَارَةً أَوْ لَهْوًا انْفَضُّوا إِلَيْهَا وَتَرَكُوكَ قَائِمًا ‏)‏ ‏.‏ قَالَ هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ حَدَّثَنَا أَحْمَدُ بْنُ مَنِيعٍ، حَدَّثَنَا هُشَيْمٌ، أَخْبَرَنَا حُصَيْنٌ، عَنْ سَالِمِ بْنِ أَبِي الْجَعْدِ، عَنْ جَابِرٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم بِنَحْوِهِ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏","v":[]}]};